        "script": "const fields = ($vars.extractReceiptFields.output && $vars.extractReceiptFields.output.ExtractionResult && $vars.extractReceiptFields.output.ExtractionResult.ResultsDocument && $vars.extractReceiptFields.output.ExtractionResult.ResultsDocument.Fields) || [];\nconst findVal = name => { const f = fields.find(f => f.FieldName === name); return f && f.Values && f.Values[0] ? f.Values[0] : null; };\nconst merchant = findVal('vendor_name') || findVal('Vendor Name') || findVal('merchant') || findVal('Merchant');\nconst date = findVal('transaction_date') || findVal('Transaction Date') || findVal('date') || findVal('Date');\nconst total = findVal('total') || findVal('Total') || findVal('total_amount') || findVal('Total Amount');\nreturn { merchant, date, total };"
