import json
# The ELK format issue: look for any null value where ELK expects a node id.
# ELK format uses handles from handleConfiguration. If a handle has id=null that would cause it.
# Let's check ALL handles in the entire definitions array of the flow
d = json.load(open('/work/output/artifacts/skill-flow-ixp-routing/receipts/ReceiptExtractionSolution/ReceiptExtraction/ReceiptExtraction.flow'))
for dfn in d['definitions']:
    for hcfg in dfn.get('handleConfiguration', []):
        for h in hcfg.get('handles', []):
            if h.get('id') is None:
                print('NULL handle id in', dfn.get('nodeType'), h)
print('done checking handles')
# Also check if any form section id is null  
for dfn in d['definitions']:
    form = dfn.get('form', {})
    for section in form.get('sections', []):
        if section.get('id') is None:
            print('NULL section id in', dfn.get('nodeType'))
        for field in section.get('fields', []):
            if field.get('id') is None:
                print('NULL field id in', dfn.get('nodeType'), field.get('component'))
print('done checking form')
"
